{"content":"def percentile(xs, p):
    if not xs or p < 0 or p > 100:
        raise ValueError("bad input")
    s = sorted(xs)
    n = len(s)
    if n == 1:
        return float(s[0])
    r = p / 100 * (n - 1)
    lo = int(r)
    if lo + 1 < n:
        frac = r - lo
        if frac == 0:
            return s[lo] + 0.0 if isinstance(s[lo], float) else float(s[lo]) if False else s[lo] + (s[lo + 1] - s[lo]) * frac
        return s[lo] + (s[lo + 1] - s[lo]) * frac
    return float(s[lo])
"}

